insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('5d8785f1-7f5b-4b79-8a75-ab1b06594c6b', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$inleiding: politieke onrust, kapitaalvlucht, agau daalt van 50 naar 35 dollarcent, inflatie stijgt$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context1.png$$,
   $$Agazia kampt sinds een half jaar met heftige politieke onrust. Als gevolg hiervan is een sterke kapitaalvlucht op gang gekomen: beleggers halen hun geld weg en kiezen voor landen met een stabiel economisch klimaat. De waarde van de munt van het land, de agau, daalde van 50 naar 35 dollarcent, met als gevolg een toename van de inflatie in Agazia. De consumptieve bestedingen stegen eerst, maar zakten daarna in.$$, 'inline'),
  ('9dc63d04-8601-4a03-8780-c3be60beeaf3', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$exporteurs zien winst stijgen; investeringsprogramma's verminderd$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context2.png$$,
   $$Terwijl exporterende bedrijven in Agazia als gevolg van de koersdaling in eerste instantie hun winst zagen stijgen, ondervonden alle bedrijven in het land nadeel van de kapitaalvlucht. Zij moesten investeringsprogramma’s verminderen of zelfs stop zetten. De vooruitzichten voor de structurele ontwikkeling van het land worden daardoor negatief beïnvloed.$$, 'inline'),
  ('4d887a0a-85fe-4ef3-aa44-e9cad62f7995', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$vraag- en aanbodfunctie van de agau (Qv, Qa, P)$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context3.png$$,
   $$Een economisch instituut heeft onderzoek gedaan naar de wisselkoers van de agau. Hierbij is de vraag- en de aanbodfunctie van de agau, in de situatie voorafgaand aan het uitbreken van de politieke onrust, als volgt bepaald:
Qᵥ = −0,2 P + 20
Qₐ = 0,3 P − 5
Qᵥ = vraag naar agaus in miljarden
Qₐ = aanbod van agaus in miljarden
P = koers van de agau in dollarcenten$$, 'inline'),
  ('c7dd805c-9c0c-4ee8-b1b3-7d2c43a12f4f', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$aanbod verandert door kapitaalvlucht: koersdaling van 50 naar 35 dollarcent$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context4.png$$,
   $$Door de kapitaalvlucht veranderde het aanbod, met de genoemde koersdaling van de agau van 50 naar 35 dollarcent als gevolg.$$, 'inline'),
  ('c6f03edf-a034-4045-ad36-0e9a1f2810ec', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$Centrale Bank overweegt interventie op de valutamarkt; speculanten$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context5.png$$,
   $$De Centrale Bank van Agazia ziet in de koersdaling van de agau meer nadelen dan voordelen voor de economie van het land. De bank overweegt daarom met aan- en verkooptransacties te interveniëren op de valutamarkt om zodoende de koers van de agau weer te laten stijgen. Met het bekend worden van dit voornemen, zorgt het optreden van speculanten op korte termijn voor een stijging van de koers van de agau.$$, 'inline'),
  ('b11e5469-5ab0-466b-9323-4e3b16ca7014', 'dffbfaf1-445b-4070-87cf-15b69a634425', $$economen vertrouwen niet op langdurige interventie$$,
   $$economie-vwo-2016-i-kapitaalvlucht-uit-agazia-context6.png$$,
   $$Economen vrezen dat dit effect niet lang zal aanhouden zonder interventie van de Centrale Bank. Zij hebben echter niet het vertrouwen dat de Centrale Bank deze interventie lang zal kunnen volhouden.$$, 'inline'),
  ('c53d6c0a-f092-4fac-8b22-c11985b7a48e', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$inleiding: Hanse heeft patent op Faldrahyl, streeft naar maximale totale winst$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context1.png$$,
   $$In een land kan farmaceutisch bedrijf Hanse dankzij een patent als enige producent het geneesmiddel Faldrahyl aanbieden. Hanse streeft naar maximale totale winst. Figuur 1 geeft voor dit product de marginale kosten, alsmede de gemiddelde- en marginale opbrengsten.$$, 'inline'),
  ('4d8c7c80-38d7-4cdc-b7f6-b3c2e55c2ad7', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$figuur 1: MK, GO en MO van Faldrahyl$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context2.png$$,
   $$figuur 1: euro''s (0-160) tegen productie in 1.000 doosjes (0-600)
GO daalt van 90 (bij 0) naar 30 (bij 600); MO daalt van 90 (bij 0) naar 0 (bij 450); MK is horizontaal op 30
MK = marginale kosten
GO = gemiddelde opbrengst
MO = marginale opbrengst$$, 'inline'),
  ('864128cb-9fb2-4505-a675-2f734fed1fa8', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$overheid stelt maximumprijs van € 50 per doosje in$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context3.png$$,
   $$De overheid van het land wil dat Faldrahyl voor een groter aantal mensen beschikbaar is en stelt daartoe een maximumprijs in van € 50 per doosje. Hanse kan met de productie voorzien in de extra vraag die ontstaat.$$, 'inline'),
  ('1e0285ad-c00b-44bb-8974-0b0d4d0f8041', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$nieuwe regering laat patent aflopen; Lako overweegt toetreding; sequentieel spel$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context4.png$$,
   $$Een nieuwe regering wil vrije toetreding tot de markt van geneesmiddelen realiseren. Zij meent dat dit ook de beste weg is om de beschikbaarheid van medicijnen te verhogen. Het patent dat Hanse heeft op Faldrahyl zal daarom niet worden verlengd. Het bedrijf Lako is geïnteresseerd in het opzetten van een productielijn voor een gelijksoortig medicijn na afloop van de patentperiode. In een poging Lako hiervan te weerhouden dreigt Hanse de prijs sterk te verlagen. De situatie waarin Hanse en Lako optreden kan worden beschouwd als een eenmalig sequentieel spel, weergegeven in de onderstaande spelboom. In de spelboom zijn de veranderingen van de winst van respectievelijk Lako en Hanse weergegeven in euro’s, rekening houdend met de afzet van zowel Lako als Hanse bij de verschillende keuzecombinaties.$$, 'inline'),
  ('c048b59f-d716-49c1-80e3-947ffa8b6cca', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$spelboom Lako-Hanse met winstveranderingen$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context5.png$$,
   $$spelboom:
Lako: wel aanbieden → Hanse: prijs gelijkhouden → +120.000; −330.000
Lako: wel aanbieden → Hanse: prijs verlagen → −60.000; −600.000
Lako: niet aanbieden → Hanse: prijs gelijkhouden → 0; 0
(winstveranderingen van respectievelijk Lako en Hanse in euro''s)$$, 'inline'),
  ('46152000-496a-423e-9163-b15b9e581563', 'd98dd10b-42ff-4168-9df1-47b1ca530ef4', $$Hanse zet 30.000 doosjes extra af; procesinnovatie verlaagt variabele kosten met € 10 per doosje$$,
   $$economie-vwo-2016-i-investeren-om-af-te-schrikken-context6.png$$,
   $$In de spelboom is meegenomen dat Hanse in geval van prijsverlaging zelf ook 30.000 doosjes meer zal afzetten dan bij toetreding bij gelijke prijs. De afdeling procesinnovatie heeft voor Hanse een mogelijkheid gevonden voor een goedkoper proces bij de voorgestelde extra productie. De variabele kosten van deze extra productie kunnen daarmee tien euro per doosje lager worden.$$, 'inline'),
  ('99b9c5d4-6c3a-49b1-8423-3daf10056274', '77578a51-aa63-4409-a929-728b34c1b2ce', $$inleiding: groei Chinese bbp door investeringen en export; laag loonniveau en groot arbeidsaanbod agrarisch$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context1.png$$,
   $$Econoom Michaels stelt in een rapport over de Chinese economie dat het bruto binnenlands product (bbp) in China tot het jaar 2011 sterk groeide door investeringen en export. Michaels meent dat de sterke groei van de export vooral mogelijk is geweest door twee factoren:
− Het loonniveau in industriële gebieden was in de voorafgaande fase van de Chinese economische ontwikkeling internationaal gezien nog erg laag.
− In agrarische gebieden bestond een zeer groot aanbod op de arbeidsmarkt. De sterke groei van de productie in de industriële gebieden werd mede mogelijk gemaakt door een omvangrijke toestroom van arbeidskrachten vanuit de agrarische gebieden.$$, 'inline'),
  ('8dfbbcad-5a94-4b25-86bb-86cb16d935fc', '77578a51-aa63-4409-a929-728b34c1b2ce', $$figuren 1a en 1b: deelmarkten industriële en agrarische gebieden$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context2.png$$,
   $$Michaels gaat bij deze analyse uit van de figuren 1a en 1b, waarin de arbeidsmarkt is onderscheiden in de deelmarkten van industriële en van agrarische gebieden. De verticale assen hebben in beide deelfiguren dezelfde schaal. De verschuivingen die in de figuren zijn weergegeven, betreffen ontwikkelingen op de arbeidsmarkt in China gedurende de jaren van sterke economische groei.$$, 'inline'),
  ('d0935e92-84df-4d32-9eb4-86181dd83011', '77578a51-aa63-4409-a929-728b34c1b2ce', $$figuur 1a arbeidsmarkt industriële gebieden en figuur 1b arbeidsmarkt agrarische gebieden$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context3.png$$,
   $$figuur 1a Arbeidsmarkt industriële gebieden: loon tegen aangeboden en gevraagde hoeveelheid arbeid; aanbodlijn eerst horizontaal, daarna stijgend; vraaglijn verschuift (gestippeld) naar rechts
figuur 1b Arbeidsmarkt agrarische gebieden: loon tegen aangeboden en gevraagde hoeveelheid arbeid; dalende vraaglijn, verticale aanbodlijn verschuift (gestippeld) naar links$$, 'inline'),
  ('a3ca6e0f-b680-4617-9325-bb178f1aeadb', '77578a51-aa63-4409-a929-728b34c1b2ce', $$industriële productie stijgt zonder loonstijging tot 2011$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context4.png$$,
   $$In de jaren tot 2011 kon de industriële productie in China toenemen zonder dat de lonen daarbij hoefden te stijgen.$$, 'inline'),
  ('735a10b8-8d80-4a01-8846-a0873d19d041', '77578a51-aa63-4409-a929-728b34c1b2ce', $$keerpunt 2011: lonen stijgen, arbeidsproductiviteit niet; werkgelegenheid onder druk$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context5.png$$,
   $$Michaels constateert dat China in 2011 een keerpunt bereikte, met voor het eerst een merkbare stijging van de lonen in de industriële gebieden. Volgens hem werd dit teweeggebracht doordat het loonverschil tussen beide deelmarkten inmiddels was opgeheven. De gemiddelde arbeidsproductiviteit in de industrie is ondertussen niet noemenswaardig gestegen. De loonstijging in de Chinese industrie kwam daarmee hoger uit dan in de industriële sectoren van de minder ontwikkelde landen in de Aziatische regio. Michaels meent dat de werkgelegenheid in de Chinese industriële sector hierdoor onder druk is komen te staan.$$, 'inline'),
  ('f4be90ff-8b3a-4a13-91fe-da2582967c70', '77578a51-aa63-4409-a929-728b34c1b2ce', $$lonen blijven stijgen ondanks inzakkende export$$,
   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-context6.png$$,
   $$Michaels constateert dat ondanks het inzakken van de industriële export de lonen in China in daaropvolgende jaren toch bleven stijgen, een signaal dat de binnenlandse productie en de vraag naar arbeid op niveau bleef of zelfs nog groeide.$$, 'inline'),
  ('23592060-d1cf-4b5c-802a-ba19abdbaed1', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$inleiding: Com en Blue streven naar maximale omzet; btw stijgt van 19% naar 21%; drie strategieën$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context1.png$$,
   $$Twee aanbieders van mobiele telecommunicatie, Com en Blue, hebben samen de consumentenmarkt van mobiele communicatie van een land in handen. Zij zijn heel alert op hun marktaandeel. Daarom streven zij naar een zo hoog mogelijke omzet en niet in eerste instantie naar maximale totale winst. Per 1 januari 2014 wordt de btw op telefonieabonnementen verhoogd van 19% naar 21%. Het management van Com bespreekt in het najaar van 2013 mogelijke strategieën naar aanleiding van deze btw-verhoging. Er worden drie strategieën onderscheiden:
− de verhoging van de btw niet doorberekenen in de prijs;
− de verhoging van de btw deels doorberekenen in de prijs;
− de verhoging van de btw volledig doorberekenen in de prijs.$$, 'inline'),
  ('3467dd3f-cbc3-41cc-8fcb-2f3b34b166a1', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$prijsafzetvergelijkingen van Com en Blue met legenda$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context2.png$$,
   $$Het management maakt bij zijn analyse gebruik van onderstaande prijsafzetvergelijkingen en prijzen van Com en Blue
Qc = − 2,3 Pc + 1,8 Pb + 85
Qb = − 1,9 Pb + 1,5 Pc + 59
Qc aantal door Com verkochte abonnementen in miljoenen
Qb aantal door Blue verkochte abonnementen in miljoenen
Pc prijs voor een abonnement bij Com in euro''s per maand (inclusief btw)
Pb prijs voor een abonnement bij Blue in euro''s per maand (inclusief btw)$$, 'inline'),
  ('e228c389-e552-48d6-9446-04e710d8e168', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$abonnementsprijzen 2013: Com € 24,99, Blue € 22,50 (incl. btw)$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context3.png$$,
   $$In 2013 waren de abonnementsprijzen per maand bij Com € 24,99 en bij Blue € 22,50, beide inclusief btw. De prijsafzetfuncties gelden voor zowel 2013 als voor 2014.$$, 'inline'),
  ('b207e391-d899-4ca3-a1fa-678b0bc1f38b', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$manager Com: vraag inelastisch bij volledig doorberekenen als Blue niet doorberekent$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context4.png$$,
   $$De manager van Com is niet bang om omzet te verliezen als hij de btw-verhoging volledig doorberekent in de prijs van een abonnement. Hij heeft de prijselasticiteit van de vraag naar abonnementen bij Com bepaald bij volledig doorberekenen. Hij ziet dat deze vraag dan inelastisch is, als Blue de btw-verhoging ondertussen niet doorberekent.$$, 'inline'),
  ('4bb2ad3e-44c8-469d-9580-4aa6714d7f33', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$staatssecretaris vreest heimelijke afspraak; marketingadviseur stelt matrix op$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context5.png$$,
   $$De staatssecretaris van economische zaken vraagt zich af of beide bedrijven misschien een heimelijke afspraak zullen maken om de btw volledig door te berekenen in de prijs. Om het keuzegedrag van Com en Blue beter in kaart te brengen, stelt een marketingadviseur een schema op met de omzetcijfers die bij de verschillende keuzecombinaties zijn te verwachten (matrix 1).$$, 'inline'),
  ('0684d831-aeab-4798-8177-1b4349c0fddf', '4482786a-2e88-45c4-bae8-eb7fd1f15aa0', $$matrix 1: verwachte omzet exclusief btw in miljoenen euro's$$,
   $$economie-vwo-2016-i-communicatie-te-duur-context6.png$$,
   $$matrix 1 verwachte omzet exclusief btw in miljoenen euro''s (Com ; Blue)
Com \ Blue | niet doorberekenen | deels doorberekenen | volledig doorberekenen
niet doorberekenen | 1.405 ; 999 | 1.438 ; 1.026 | 1.419 ; 1.002
deels doorberekenen | 1.480 ; 1.035 | 1.473 ; 1.049 | 1.411 ; 1.020
volledig doorberekenen | 1.408 ; 1.011 | 1.455 ; 1.050 | 1.423 ; 1.014$$, 'inline'),
  ('f24a47ef-17c7-488b-9ca9-46baf52528e7', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$inleiding: AOVZ introduceert arbeidsongeschiktheidsverzekering voor zzp'ers, uitkering € 200.000, uniforme premie$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context1.png$$,
   $$De particuliere verzekeringsmaatschappij AOVZ wil in 2017 een vrijwillige arbeidsongeschiktheidsverzekering introduceren voor de doelgroep zelfstandigen zonder personeel (zzp’ers). AOVZ geeft met deze verzekering zzp’ers in geval van ernstige arbeidsongeschiktheid uitzicht op een eenmalige uitkering van € 200.000. Van de zzp’ers in de regio waar AOVZ start, heeft 50% een fysiek zwaar beroep en 50% een fysiek licht beroep. De directie overweegt voor 2017 in eerste instantie een uniforme premie. De tabellen 1 en 2 vermelden verwachtingen van de directie voor 2017.$$, 'inline'),
  ('a1e8ab4a-d760-4fc9-9f18-fbd23573697f', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$tabel 1: gegevens verzekeringnemers AOVZ 2017$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context2.png$$,
   $$tabel 1 gegevens verzekeringnemers AOVZ 2017
doelgroep | aantal verzekeringsnemers per groep | uniforme jaarpremie per persoon | kans op arbeidsongeschiktheid per groep | uit te keren bij arbeidsongeschiktheid per verzekeringsnemer
zzp''ers met een fysiek zwaar beroep | 8.000 | 850 euro | 1/200 | 200.000 euro
zzp''ers met een fysiek licht beroep | 1.000 | 850 euro | 1/500 | 200.000 euro$$, 'inline'),
  ('bd8c0fa4-4c12-4548-b2e1-e28d5800a20e', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$tabel 2: verwachte kosten van AOVZ in 2017$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context3.png$$,
   $$tabel 2 verwachte kosten van AOVZ in 2017
totale kosten in verband met: | constant / variabel | nadere informatie
loon, rente & afschrijving | constant | in totaal 400.000 euro per jaar
administratie | variabel | 15 euro per klant
schade-uitkeringen | variabel | afhankelijk van de groep$$, 'inline'),
  ('e10cb0ca-c52c-4499-bb34-d7e2d0498deb', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$directie streeft naar maximale totale winst; uniforme premie 850 euro dekt kosten niet$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context4.png$$,
   $$De directie streeft naar een zo groot mogelijke totale winst. In 2017 zullen bij de gekozen uniforme jaarpremie van 850 euro de kosten echter niet gedekt kunnen worden.$$, 'inline'),
  ('07de7983-0f17-458a-824b-6eb0d3608678', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$directielid vreest moral hazard; voorzitter acht dat verwaarloosbaar$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context5.png$$,
   $$Een directielid vreest dat door moral hazard bij verzekerde zzp-ers het verlies groter kan uitvallen dan verwacht. De voorzitter van de directie acht de kans op moral hazard bij een arbeidsongeschiktheidsverzekering te verwaarlozen.$$, 'inline'),
  ('9b7dd2a6-6b3b-4222-90bb-cdeb8012c12d', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$directie past premiedifferentiatie toe; figuren 1 en 2$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context6.png$$,
   $$De directie besluit om vanaf 2017 toch premiedifferentiatie toe te passen voor de in tabel 1 onderscheiden groepen zzp’ers. Zij gaat daarbij uit van de informatie over opbrengsten en kosten voor beide doelgroepen, zoals weergegeven in de figuren 1 en 2.$$, 'inline'),
  ('ac0e303d-4d8f-435e-b10b-1fc4dcfd534c', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$figuur 1: verzekerden met een zwaar beroep (MO, GO, MK)$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context7.png$$,
   $$figuur 1 verzekerden bij AOVZ met een zwaar beroep
€ (0-1.800) tegen Q₁ (aantal verzekerden x100 uit groep 1, 0-150)
GO₁ daalt van 1.800 naar 0 bij Q₁ = 150; MO₁ daalt van 1.800 naar 0 bij Q₁ = 75; MK₁ horizontaal op 1.015$$, 'inline'),
  ('90fb8661-3405-4453-993b-16c985951ce5', '6ddb5ade-d3b8-43a5-9574-3cd45e19aa94', $$figuur 2: verzekerden met een licht beroep (MO, GO, MK) met legenda$$,
   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-context8.png$$,
   $$figuur 2 verzekerden bij AOVZ met een licht beroep
€ (0-1.400) tegen Q₂ (aantal verzekerden x100 uit groep 2, 0-30)
GO₂ en MO₂ dalen lineair vanaf 1.200 bij Q₂ = 0 (MO₂ twee keer zo steil als GO₂); MK₂ horizontaal op 415
MO = Marginale Opbrengsten
MK = Marginale kosten
GO = Gemiddelde Opbrengsten$$, 'inline'),
  ('12c3b8ef-2b49-4d7a-bfb7-12cdc0de1c3a', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$inleiding: daling netto participatiegraad laagopgeleiden, armoedeval; doelen regering$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context1.png$$,
   $$De regering van een land is bezorgd over de daling van de netto participatiegraad, dat wil zeggen het aandeel werkzame mensen in de potentiële beroepsbevolking (alle mensen tussen 18 en 66 jaar). Voor mensen met een lage opleiding is de netto participatiegraad gedurende de laatste jaren afgenomen van 52% naar 45%. Volgens de regering is deze daling vooral te wijten aan de zogeheten ‘armoedeval’: als laagopgeleide mensen vanuit een uitkeringssituatie in loondienst komen gaat hun netto jaarinkomen er bijna niet op vooruit. De regering wil (het accepteren van) betaald werk voor met name laagopgeleide mensen financieel aantrekkelijker maken. Daarnaast stelt de regering zich ten doel om de verdeling van de netto inkomens minder scheef te maken. Tabel 1 geeft de tarieven voor de inkomstenbelasting in 2016. Belasting wordt geheven over zowel arbeidsinkomen als inkomen uit uitkeringen.$$, 'inline'),
  ('76486692-e7cd-4b2d-9a25-f7e7b9875950', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$tabel 1: schijven en tarieven inkomensheffing in 2016$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context2.png$$,
   $$tabel 1 schijven en tarieven inkomensheffing in 2016
Vanaf belastbaar jaarinkomen | Tot en met belastbaar jaarinkomen van | Tarief inkomstenbelasting
0 euro | 13.000 euro | 25%
13.001 euro | 57.000 euro | 40%
57.001 euro | | 50%$$, 'inline'),
  ('9eb80a59-b252-41ff-92a0-dc0a714a41d5', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$twee aanpassingen: algemene heffingskorting of arbeidskorting van 1.000 euro$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context3.png$$,
   $$De regering overweegt voor 2017 een van onderstaande aanpassingen aan te brengen in de inkomstenbelasting:
1 de introductie van een algemene heffingskorting van 1.000 euro per jaar voor iedere belastingplichtige, of
2 de introductie van een arbeidskorting van 1.000 euro per jaar voor iedereen met een betaalde baan.$$, 'inline'),
  ('8bfe4d96-1f08-4a82-88b7-4f4b7db7f5c2', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$overheid kiest aanpassing 2; schijventarief blijft gelijk$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context4.png$$,
   $$De overheid kiest voor invoering van aanpassing 2. Het schijventarief blijft in 2017 hetzelfde als in 2016.$$, 'inline'),
  ('ee9e1290-8948-402b-aa5d-ff6c5371ce3b', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$Jannie van Agt: bijstand netto 12.000/12.200 euro of baan met brutoloon 16.000 euro; bewering vriendin$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context5.png$$,
   $$Jannie van Agt houdt van haar bijstandsuitkering in 2016 netto 12.000 euro over. Begin januari 2017 heeft zij de kans om als medewerkster in een cateringbedrijf te werken. Haar brutojaarloon in 2017 zal 16.000 euro bedragen. Zonder werk zou haar nettobijstandsuitkering voor 2017 12.200 euro zijn. Haar vriendin rekent haar voor dat ze dankzij de aanpassing in de inkomstenbelasting die baan beter wel kan accepteren: “Het extra netto-inkomen dat je ontvangt zal ruim het dubbele zijn van het geld dat je extra krijgt als je in de bijstand blijft.”$$, 'inline'),
  ('a016e8ed-ac7f-422b-82a6-b62a069d716b', '072f1a59-e7d0-43d8-88f0-3fd2997a3264', $$minister: kortingen verhogen besteedbaar inkomen en beïnvloeden conjunctuur$$,
   $$economie-vwo-2016-i-werken-moet-lonen-context6.png$$,
   $$De minister van financiën argumenteert: “De introductie van elk van de kortingen leidt tot een hoger besteedbaar inkomen en is daarmee van invloed op de conjunctuur. Langs deze weg kan ook de bereidheid van mensen om zich aan te bieden op de arbeidsmarkt toenemen.”$$, 'inline');

