   $$economie-vwo-2016-i-chinese-arbeidsmarkt-op-keerpunt-vraag11.png$$, $$1p 11 Verklaar de verschuiving van de vraaglijn op de arbeidsmarkt in industriële gebieden met behulp van de tekst.$$, array['99b9c5d4-6c3a-49b1-8423-3daf10056274', '8dfbbcad-5a94-4b25-86bb-86cb16d935fc', 'd0935e92-84df-4d32-9eb4-86181dd83011']::uuid[]),
