   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Speltheorie"}]'::jsonb,
   '["pay-off matrix", "prijsafspraak", "kartel", "prikkel tot afwijken", "gevangenendilemma"]'::jsonb,
