   '[{"domain": "Risico en Informatie", "subdomain": "Risico verzekeren"}]'::jsonb,
   '["averechtse selectie", "uniforme premie", "informatieasymmetrie", "hoog risico", "verzekeringnemers"]'::jsonb,
