   $$economie-vwo-2016-i-geschikte-arbeidsongeschiktheidsverzekeringen-vraag20.png$$, $$2p 20 Verklaar aan de hand van tabel 1 en de tekst hoe dit verlies mede kan zijn veroorzaakt door het optreden van averechtse selectie.$$, array['f24a47ef-17c7-488b-9ca9-46baf52528e7', 'a1e8ab4a-d760-4fc9-9f18-fbd23573697f', 'e10cb0ca-c52c-4499-bb34-d7e2d0498deb']::uuid[]),
